def _insert(doctype, values, key_field):
    key = values.get(key_field)
    if key and not frappe.db.exists(doctype, {key_field: key}):
        frappe.get_doc(dict(doctype=doctype, **values)).insert(ignore_permissions=True)

def execute():
    frappe.reload_doc("wafd_one", "doctype", "wafd_nationality")
    frappe.reload_doc("wafd_one", "doctype", "wafd_hotel_undertaking")
    frappe.reload_doc("wafd_one", "doctype", "wafd_mission")
    frappe.reload_doc("wafd_one", "doctype", "wafd_ingredient")
    for name, ar, en, iso2, iso3, hajj in NATIONALITIES:
        _insert("WAFD Nationality", {"nationality_name": name, "country_name_ar": ar, "country_name_en": en, "iso2": iso2, "iso3": iso3, "is_hajj_source": hajj, "enabled": 1}, "nationality_name")
    for category, names in INGREDIENTS.items():
        for index, name in enumerate(names, 1):
            _insert("WAFD Ingredient", {"ingredient_name": name, "item_code": "RC78-" + str(abs(hash(category + name)))[:9], "category": category, "uom": "حبة / Piece" if category in ("تغليف / Packaging","منظفات / Cleaning","تعقيم وسلامة / Hygiene & Safety","أدوات تشغيل / Operating Supplies") else "كجم / Kg", "status": "نشط / Active", "storage_condition": "حسب تعليمات المصنع / Manufacturer Instructions", "verification_status": "تشغيلي داخلي / Internal Operational", "source_authority": "WAFD ONE operational master data", "last_verified_on": nowdate(), "source_notes": "يجب إدخال تكلفة المورد الفعلية ووحدة الشراء قبل اعتماد التكلفة."}, "ingredient_name")
    for name, cat, nationalities in RECIPES:
        _insert("WAFD Recipe", {"recipe_name": name, "meal_category": cat, "yield_quantity": 100, "status": "نشطة / Active", "cuisine": nationalities, "suitable_nationalities": nationalities, "verification_status": "تشغيلي داخلي / Internal Operational", "source_authority": "WAFD ONE Hajj catering operational library", "last_verified_on": nowdate(), "source_notes": "قالب تشغيلي أولي؛ يجب اعتماد المقادير النهائية من مسؤول الإنتاج والجودة قبل التشغيل."}, "recipe_name")
    # Ensure Indonesia mission is available
    _insert("WAFD Mission", {"mission_name":"بعثة الحج الإندونيسية / Indonesian Hajj Mission", "official_name":"Indonesian Hajj Affairs Office", "country":"إندونيسيا / Indonesia", "mission_type":"مكتب شؤون حجاج / Hajj Affairs Office", "hajj_season":"1447 AH", "status":"نشط / Active", "source_authority":"Saudi Ministry of Hajj and Umrah / operational verification required", "verification_status":"يحتاج مراجعة / Needs Review", "last_verified_on":nowdate(), "source_notes":"يجب تحديث بيانات التواصل من العقد أو المصدر الرسمي الموسمي."}, "mission_name")
    frappe.db.commit()
